import React, { useCallback, useEffect, useRef, useState } from "react";
import { cn } from "@/app/lib/utils";
import StarsBackground from "./stars-background";

export type ShootingStarsProps = {
  minSpeed?: number; // px per second for cruise phase
  maxSpeed?: number; // px per second for cruise phase
  minDelay?: number; // ms between spawns
  maxDelay?: number; // ms between spawns
  initialDelayMs?: number; // ms before the first star spawns
  starColor?: string;
  trailColor?: string;
  starWidth?: number; // px trail length
  starHeight?: number; // px thickness
  minTravelPx?: number; // px minimal travel distance
  className?: string;
};

type ShootingInstance = {
  id: number;
  startLeftPx: number;
  startTopPx: number;
  endLeftPx: number;
  endTopPx: number;
  angleRad: number;
  windupDistancePx: number;
  accDistancePx: number;
  windupDurationMs: number;
  accDurationMs: number;
  explosiveDurationMs: number;
  fadeDurationMs: number;
  phase: "spawning" | "windup" | "accelerating" | "explosive" | "fading";
};

function randomBetween(min: number, max: number) {
  return Math.random() * (max - min) + min;
}

function pickOffscreenPoint(width: number, height: number, margin: number) {
  const side = Math.floor(Math.random() * 4); // 0 top, 1 right, 2 bottom, 3 left
  switch (side) {
    case 0:
      return { x: randomBetween(-margin, width + margin), y: -margin };
    case 1:
      return { x: width + margin, y: randomBetween(-margin, height + margin) };
    case 2:
      return { x: randomBetween(-margin, width + margin), y: height + margin };
    default:
      return { x: -margin, y: randomBetween(-margin, height + margin) };
  }
}

export default function ShootingStars({
  minSpeed = 500,
  maxSpeed = 900,
  minDelay = 2500,
  maxDelay = 5000,
  initialDelayMs = 0,
  starColor = "#9E00FF",
  trailColor = "#FFFFFF",
  starWidth = 140,
  starHeight = 2,
  minTravelPx = 700,
  className,
}: ShootingStarsProps) {
  const wrapperRef = useRef<HTMLDivElement | null>(null);
  const [containerSize, setContainerSize] = useState<{ width: number; height: number }>({ width: 0, height: 0 });
  const [shooting, setShooting] = useState<ShootingInstance | null>(null);

  useEffect(() => {
    const element = wrapperRef.current;
    if (!element) return;
    const resizeObserver = new ResizeObserver((entries) => {
      for (const entry of entries) {
        const box = entry.contentRect;
        setContainerSize({ width: Math.max(0, Math.floor(box.width)), height: Math.max(0, Math.floor(box.height)) });
      }
    });
    resizeObserver.observe(element);
    const box = element.getBoundingClientRect();
    setContainerSize({ width: Math.max(0, Math.floor(box.width)), height: Math.max(0, Math.floor(box.height)) });
    return () => resizeObserver.disconnect();
  }, []);

  useEffect(() => {
    let cancelled = false;
    let timeoutId: number | undefined;

    const scheduleNext = () => {
      const delay = Math.max(0, Math.floor(randomBetween(minDelay, maxDelay)));
      timeoutId = window.setTimeout(() => {
        if (cancelled) return;
        triggerShootingStar();
        scheduleNext();
      }, delay);
    };

    const triggerShootingStar = () => {
      const { width, height } = containerSize;
      if (!width || !height) return;
      const margin = 120;
      const diagonal = Math.hypot(width, height);
      const desiredTotalDistance = Math.max(minTravelPx, diagonal + margin * 2);

      // Compute viewport rect relative to container
      const el = wrapperRef.current;
      const rect = el ? el.getBoundingClientRect() : { top: 0, height } as DOMRect;
      const viewportTopInContainer = -rect.top;
      const viewportBottomInContainer = viewportTopInContainer + window.innerHeight;

      // Choose start outside viewport but within the page (container)
      let startX = randomBetween(0, width);
      let startY = 0;
      const topRangeMax = Math.max(0, viewportTopInContainer - margin);
      const bottomRangeMin = Math.min(height, viewportBottomInContainer + margin);
      const topRangeAvailable = topRangeMax > 0;
      const bottomRangeAvailable = bottomRangeMin < height;
      if (topRangeAvailable && bottomRangeAvailable) {
        if (Math.random() < 0.5) {
          startY = randomBetween(0, topRangeMax);
        } else {
          startY = randomBetween(bottomRangeMin, height);
        }
      } else if (topRangeAvailable) {
        startY = randomBetween(0, topRangeMax);
      } else if (bottomRangeAvailable) {
        startY = randomBetween(bottomRangeMin, height);
      } else {
        // Fallback: start horizontally outside viewport
        startX = Math.random() < 0.5 ? -margin : width + margin;
        startY = randomBetween(0, height);
      }

      // Bias direction roughly towards viewport center to increase visibility
      const viewportCenterX = width / 2;
      const viewportCenterY = viewportTopInContainer + Math.min(window.innerHeight, height) / 2;
      const baseAngle = Math.atan2(viewportCenterY - startY, viewportCenterX - startX);
      const theta = baseAngle + randomBetween(-0.5, 0.5);
      const ux = Math.cos(theta);
      const uy = Math.sin(theta);

      const endX = startX + ux * desiredTotalDistance;
      const endY = startY + uy * desiredTotalDistance;

      const deltaX = endX - startX;
      const deltaY = endY - startY;
      const distance = Math.hypot(deltaX, deltaY);
      const angleRad = Math.atan2(deltaY, deltaX);

      // Phase distances
      const windupDistancePx = Math.min(120, Math.max(60, distance * 0.06));
      const accDistancePx = Math.min(260, Math.max(distance * 0.18, minTravelPx * 0.18));

      // Phase durations
      const windupDurationMs = Math.floor(randomBetween(800, 1100));
      const accDurationMs = Math.floor(randomBetween(600, 900));
      const explosiveDurationMs = Math.floor(randomBetween(1500, 2500));

      const instance: ShootingInstance = {
        id: Date.now(),
        startLeftPx: startX,
        startTopPx: startY,
        endLeftPx: endX,
        endTopPx: endY,
        angleRad,
        windupDistancePx,
        accDistancePx,
        windupDurationMs,
        accDurationMs,
        explosiveDurationMs,
        fadeDurationMs: 500,
        phase: "spawning",
      };
      setShooting(instance);
      requestAnimationFrame(() => {
        setShooting((prev) => (prev && prev.id === instance.id ? { ...prev, phase: "windup" } : prev));
      });
    };

    const initialDelay = Math.max(0, Math.floor(initialDelayMs));
    timeoutId = window.setTimeout(() => {
      if (cancelled) return;
      triggerShootingStar();
      scheduleNext();
    }, initialDelay);
    return () => {
      cancelled = true;
      if (timeoutId) window.clearTimeout(timeoutId);
    };
  }, [containerSize.width, containerSize.height, minDelay, maxDelay, minSpeed, maxSpeed, minTravelPx, initialDelayMs]);

  const handleTransitionEnd = useCallback(() => {
    setShooting((prev) => {
      if (!prev) return prev;
      if (prev.phase === "windup") {
        return { ...prev, phase: "accelerating" };
      }
      if (prev.phase === "accelerating") {
        return { ...prev, phase: "explosive" };
      }
      if (prev.phase === "explosive") {
        return { ...prev, phase: "fading" };
      }
      return null;
    });
  }, []);

  // Compute transforms based on phase
  const getTransformForPhase = (s: ShootingInstance) => {
    const { startLeftPx, startTopPx, endLeftPx, endTopPx, windupDistancePx, accDistancePx } = s;
    const dx = endLeftPx - startLeftPx;
    const dy = endTopPx - startTopPx;
    const distance = Math.hypot(dx, dy);
    if (distance === 0) return `translate(${startLeftPx}px, ${startTopPx}px)`;
    const ux = dx / distance;
    const uy = dy / distance;
    if (s.phase === "spawning") {
      return `translate(${startLeftPx}px, ${startTopPx}px)`;
    }
    if (s.phase === "windup") {
      const wx = startLeftPx + ux * windupDistancePx;
      const wy = startTopPx + uy * windupDistancePx;
      return `translate(${wx}px, ${wy}px)`;
    }
    if (s.phase === "accelerating") {
      const ax = startLeftPx + ux * (windupDistancePx + accDistancePx);
      const ay = startTopPx + uy * (windupDistancePx + accDistancePx);
      return `translate(${ax}px, ${ay}px)`;
    }
    // explosive and fading both at end position
    return `translate(${endLeftPx}px, ${endTopPx}px)`;
  };

  const getTransitionForPhase = (s: ShootingInstance) => {
    if (s.phase === "spawning") return "none";
    if (s.phase === "windup") {
      return `transform ${s.windupDurationMs}ms cubic-bezier(0.2, 0.0, 0.0, 1)`; // very slow start
    }
    if (s.phase === "accelerating") {
      return `transform ${s.accDurationMs}ms cubic-bezier(0.8, 0.0, 1, 1)`; // fast acceleration
    }
    if (s.phase === "explosive") {
      return `transform ${s.explosiveDurationMs}ms linear`;
    }
    return "none";
  };

  const getOpacityForPhase = (s: ShootingInstance) => {
    if (s.phase === "spawning") return 0.0; // start invisible
    if (s.phase === "windup") return 0.6; // fade in during windup
    if (s.phase === "fading") return 0.0;
    return 0.6; // accelerating and explosive
  };

  const getOpacityTransitionForPhase = (s: ShootingInstance) => {
    if (s.phase === "windup") {
      return `opacity ${s.windupDurationMs}ms ease-in`;
    }
    if (s.phase === "fading") {
      return `opacity ${s.fadeDurationMs}ms ease-out`;
    }
    return "none";
  };

  const isTrailPhase = (s: ShootingInstance) => s.phase === "accelerating" || s.phase === "explosive";
  const getWidthForPhase = (s: ShootingInstance) => (isTrailPhase(s) ? starWidth : Math.max(starHeight * 2, 6));

  const getBackgroundForPhase = (s: ShootingInstance) => {
    return isTrailPhase(s)
      ? `linear-gradient(90deg, transparent 0%, ${trailColor} 60%, ${starColor} 100%)`
      : starColor;
  };

  return (
    <div
      ref={wrapperRef}
      className={cn(
        "pointer-events-none relative size-full overflow-hidden bg-gradient-to-br from-slate-900 to-slate-800",
        className
      )}
    >
      <StarsBackground className="absolute inset-0 z-0" />
      {shooting && (
        <div
          key={shooting.id}
          className="absolute"
          onTransitionEnd={handleTransitionEnd}
          style={{
            left: 0,
            top: 0,
            transform: getTransformForPhase(shooting),
            transition: getTransitionForPhase(shooting),
          }}
        >
          <div
            style={{
              width: `${getWidthForPhase(shooting)}px`,
              height: `${starHeight}px`,
              background: getBackgroundForPhase(shooting),
              filter: "drop-shadow(0 0 6px rgba(255,255,255,0.9))",
              borderRadius: `${starHeight}px`,
              transform: `rotate(${shooting.angleRad}rad)`,
              opacity: getOpacityForPhase(shooting),
              transition: getOpacityTransitionForPhase(shooting),
            }}
          />
        </div>
      )}
    </div>
  );
}

"use client";

import React, { useEffect, useRef, useState } from "react";
import { cn } from "@/app/lib/utils";

export type StarsBackgroundProps = {
  starDensity?: number; // stars per pixel area
  allStarsTwinkle?: boolean; // if false, stars are static
  twinkleProbability?: number; // when allStarsTwinkle is false
  minTwinkleSpeed?: number; // seconds
  maxTwinkleSpeed?: number; // seconds
  className?: string;
};

type StarDefinition = {
  id: number;
  xPercent: number; // 0..100
  yPercent: number; // 0..100
  sizePx: number;
  willTwinkle: boolean;
  twinkleDurationSec: number;
  twinkleDelaySec: number;
  glowDurationSec: number;
  glowDelaySec: number;
  brightness: number; // 0..1 for static brightness
};

function randomBetween(min: number, max: number) {
  return Math.random() * (max - min) + min;
}

export default function StarsBackground({
  starDensity = 0.00015,
  allStarsTwinkle = false,
  twinkleProbability = 0.7,
  minTwinkleSpeed = 0.5,
  maxTwinkleSpeed = 1,
  className,
}: StarsBackgroundProps) {
  const wrapperRef = useRef<HTMLDivElement | null>(null);
  const [containerSize, setContainerSize] = useState<{ width: number; height: number }>({ width: 0, height: 0 });
  const [stars, setStars] = useState<StarDefinition[]>([]);

  useEffect(() => {
    const element = wrapperRef.current;
    if (!element) return;

    const resizeObserver = new ResizeObserver((entries) => {
      for (const entry of entries) {
        const box = entry.contentRect;
        setContainerSize({ width: Math.max(0, Math.floor(box.width)), height: Math.max(0, Math.floor(box.height)) });
      }
    });
    resizeObserver.observe(element);
    const box = element.getBoundingClientRect();
    setContainerSize({ width: Math.max(0, Math.floor(box.width)), height: Math.max(0, Math.floor(box.height)) });
    return () => resizeObserver.disconnect();
  }, []);

  useEffect(() => {
    if (containerSize.width === 0 || containerSize.height === 0) return;
    const area = containerSize.width * containerSize.height;
    const targetCount = Math.max(8, Math.floor(area * starDensity));
    const created: StarDefinition[] = [];
    for (let i = 0; i < targetCount; i++) {
      const willTwinkle = allStarsTwinkle || Math.random() < twinkleProbability;
      const twinkleDurationSec = willTwinkle ? randomBetween(minTwinkleSpeed, maxTwinkleSpeed) : 0;
      const twinkleDelaySec = willTwinkle ? Math.random() * 2 : 0;
      const glowDurationSec = willTwinkle ? randomBetween(0.6, 1.2) : 0;
      const glowDelaySec = willTwinkle ? Math.random() * 1.5 : 0;
      const brightness = Math.random() * 0.6 + 0.35; // 0.35..0.95
      created.push({
        id: i,
        xPercent: Math.random() * 100,
        yPercent: Math.random() * 100,
        sizePx: Math.random() < 0.85 ? 1 : 2,
        willTwinkle,
        twinkleDurationSec,
        twinkleDelaySec,
        glowDurationSec,
        glowDelaySec,
        brightness,
      });
    }
    setStars(created);
  }, [containerSize.width, containerSize.height, starDensity, allStarsTwinkle, twinkleProbability, minTwinkleSpeed, maxTwinkleSpeed]);

  return (
    <div ref={wrapperRef} className={cn("pointer-events-none relative h-full w-full overflow-hidden", className)}>
      <div className="absolute inset-0">
        {stars.map((star) => {
          const left = `${star.xPercent}%`;
          const top = `${star.yPercent}%`;
          const size = `${star.sizePx}px`;
          const twinkleAnimation = star.willTwinkle
            ? `${star.twinkleDurationSec}s twinkle ease-in-out ${star.twinkleDelaySec}s infinite alternate`
            : "none";
          const glowAnimation = star.willTwinkle ? `${star.glowDurationSec}s glowPulse ease-in-out ${star.glowDelaySec}s infinite alternate` : "none";

          // App is dark-only: always render light stars on dark background.
          const backgroundGradient =
            "radial-gradient(circle, rgba(255,255,255,0.95) 0%, rgba(255,255,255,0.35) 40%, rgba(255,255,255,0.0) 70%)";
          const boxShadow = "0 0 4px rgba(255,255,255,0.6), 0 0 8px rgba(255,255,255,0.35)";

          return (
            <span
              key={star.id}
              className="absolute rounded-full"
              style={{
                left,
                top,
                width: size,
                height: size,
                background: backgroundGradient,
                boxShadow: boxShadow,
                animation: `${glowAnimation}${twinkleAnimation === "none" ? "" : ", " + twinkleAnimation}`,
                opacity: star.brightness,
              }}
            />
          );
        })}
      </div>
      {/* No global animations when stars are static; twinkle/glow keyframes are omitted to reduce work */}
    </div>
  );
}

'use client'

import { useTheme } from '../lib/theme-provider'
import { useEffect, useState } from 'react'

/**
 * Theme toggle button component that cycles through light, dark, and system themes.
 * Prevents hydration mismatch by only rendering after mount.
 * Displays appropriate icon based on current theme state.
 * 
 * @example
 * ```tsx
 * <ThemeToggle />
 * ```
 */
export default function ThemeToggle() {
  const { theme, setTheme } = useTheme()
  // Track mount state to prevent hydration mismatch
  const [mounted, setMounted] = useState(false)

  useEffect(() => {
    setMounted(true)
  }, [])

  // Render placeholder until mounted to avoid hydration issues
  if (!mounted) {
    return (
      <div className="w-9 h-9 rounded-md border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800"></div>
    )
  }

  // Cycle through themes: light -> dark -> system -> light
  const toggleTheme = () => {
    console.log('toggleTheme', theme)
    if (theme === 'light') {
      setTheme('dark')
    } else if (theme === 'dark') {
      setTheme('system')
    } else {
      setTheme('light')
    }
  }

  const getIcon = () => {
    switch (theme) {
      case 'light':
        return (
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z" />
          </svg>
        )
      case 'dark':
        return (
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z" />
          </svg>
        )
      case 'system':
        return (
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9.75 17L9 20l-1 1h8l-1-1-.75-3M3 13h18M5 17h14a2 2 0 002-2V5a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" />
          </svg>
        )
      default:
        return null
    }
  }

  const getTitle = () => {
    switch (theme) {
      case 'light':
        return 'Switch to dark mode'
      case 'dark':
        return 'Switch to system mode'
      case 'system':
        return 'Switch to light mode'
      default:
        return 'Toggle theme'
    }
  }

  return (
    <button
      onClick={toggleTheme}
      className="inline-flex items-center justify-center w-9 h-9 rounded-md border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-700 hover:text-slate-900 dark:hover:text-white transition-colors focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 dark:focus:ring-offset-slate-800"
      title={getTitle()}
      aria-label={getTitle()}
    >
      {getIcon()}
    </button>
  )
}
